  message += '❌ Az elmúlt 7 napban nincs rögzített munkaidő.\n';
} else {
  message += `✅ **${totalRecords}** bejegyzés az elmúlt 7 napban.\n\n`;

  // Dátum szerint csoportosítás
  const byDate = {};
  records.forEach(record => {
    const date = record.json.Dátum || 'Ismeretlen';
    if (!byDate[date]) {
      byDate[date] = [];
    }
    byDate[date].push(record.json.Megjegyzés || 'Nincs megjegyzés');
  });

  // Dátum szerint rendezés
  const sortedDates = Object.keys(byDate).sort().reverse();

  sortedDates.forEach(date => {
    message += `\n📆 **${date}**\n`;
    byDate[date].forEach((megjegyzes, index) => {
      message += `  ${index + 1}. ${megjegyzes}\n`;
    });
  });
}

message += '\n💡 Használd a /statusz parancsot a mai státuszhoz.';

return [{
  json: {
    message: message,
    chatId: chatId,
    totalRecords: totalRecords
  }
}];

