// Heti hiba statisztikĂˇk szĂˇmĂ­tĂˇsa
const errors = $input.all();

const totalErrors = errors.length;
const criticalErrors = errors.filter(e => e.json.Severity === 'critical').length;
const errorErrors = errors.filter(e => e.json.Severity === 'error').length;
const warningErrors = errors.filter(e => e.json.Severity === 'warning').length;

// Workflow szerint csoportosĂ­tĂˇs
const byWorkflow = {};
errors.forEach(error => {
  const workflow = error.json['Workflow ID'] || 'unknown';
  if (!byWorkflow[workflow]) {
    byWorkflow[workflow] = 0;
  }
  byWorkflow[workflow]++;
});

let message = `đź“Š **Heti Hiba Ă–sszesĂ­tĹ‘**\n\n`;
message += `**Ă–sszes hiba:** ${totalErrors}\n`;
message += `â€˘ Kritikus: ${criticalErrors}\n`;
message += `â€˘ Hiba: ${errorErrors}\n`;
message += `â€˘ FigyelmeztetĂ©s: ${warningErrors}\n\n`;

if (Object.keys(byWorkflow).length > 0) {
  message += `**Workflow szerint:**\n`;
  Object.entries(byWorkflow).forEach(([workflow, count]) => {
    message += `â€˘ ${workflow}: ${count}\n`;
  });
}

if (totalErrors === 0) {
  message += '\nâś… Nincs hiba az elmĂşlt hĂ©ten!';
} else if (criticalErrors > 0) {
  message += '\nâš ď¸Ź **Figyelem:** Kritikus hibĂˇk Ă©szlelve!';
}

return [{
  json: {
    message: message,
    totalErrors: totalErrors,
    criticalErrors: criticalErrors,
    errorErrors: errorErrors,
    warningErrors: warningErrors
  }
}];

