return results;

// EllenĹ‘rzĂ©s: van-e munkaidĹ‘ bejegyzĂ©s a hĂ©ten
const employee = $('MunkatĂˇrsak FeldolgozĂˇs').item.json;
const worktimeRecords = $input.all();

