  message += 'â€˘ "Tegnap 6 ĂłrĂˇt dolgoztam"';
}

message += '\n\nđź“Š HasznĂˇld a /statusz parancsot a mai stĂˇtuszhoz, vagy /het a heti Ă¶sszesĂ­tĹ‘hĂ¶z.';

return [{
